7: export function updaterAction(state: UpdaterState | undefined) {
8:   if (!state) return { label: "settings.updates.action.checkNow" as const }
9:   switch (state.status) {
10:     case "checking":
11:       return { label: "settings.updates.action.checking" as const }
12:     case "downloading":
13:       return { label: "settings.updates.action.downloading" as const }
14:     case "ready":
15:       return { label: "toast.update.action.installRestart" as const, run: "install" as const }
16:     case "installing":
17:       return { label: "settings.updates.action.installing" as const }
18:     case "disabled":
19:       return { label: "settings.updates.action.checkNow" as const }
20:     default:
21:       return { label: "settings.updates.action.checkNow" as const, run: "check" as const }
22:   }
23: }

